  function login(){const ready=configured();return '<section class="entry-panel entry-panel-login">'+entryPanelKicker('VOTRE CARNET SCOLAIRE','YOUR SCHOOL RECORD')+(payReturn?'<p class="entry-note pay-return" role="status">'+t('Retour de la page de paiement. Connectez-vous : votre paiement est vérifié automatiquement et votre espace s’ouvre dès qu’il est confirmé.','Back from the payment page. Sign in: your payment is checked automatically and your space opens as soon as it is confirmed.')+'</p>':'')+'<h1>'+t('Heureux de vous retrouver.','Welcome back.')+'</h1><p class="entry-lead">'+t('La maison, l’école et l’accompagnement avancent dans le même sens.','Home, school and learning support move in the same direction.')+'</p><img class="entry-family-art" src="assets/entry-family.webp" alt="'+t('Une mère accompagne sa fille dans ses devoirs.','A mother helps her daughter with homework.')+'" width="960" height="540" fetchpriority="high"><section class="entry-form-block"><h2>'+t('Connectez-vous à votre espace.','Sign in to your space.')+'</h2>'+(ready?'<p class="entry-note">'+t('Votre espace personnel est sauvegardé. Sur un appareil partagé, déconnectez-vous après utilisation.','Your private space is saved. Sign out after using a shared device.')+'</p>':'')+(!ready?'<p class="entry-note">'+t('Les comptes personnels ne sont pas encore ouverts. Vous pouvez découvrir le parcours avec des profils fictifs.','Personal accounts are not open yet. Explore the journey with fictional profiles.')+'</p>':'')+'<form id="entry-login-form"><label for="entry-email">'+t('Adresse e-mail','Email address')+'</label><input id="entry-email" type="email" autocomplete="username" placeholder="'+t('Votre adresse e-mail','Your email address')+'" '+(!ready?'disabled':'required')+'><label for="entry-password">'+t('Mot de passe','Password')+'</label><div class="entry-password"><input id="entry-password" type="password" autocomplete="current-password" placeholder="'+t('Votre mot de passe','Your password')+'" '+(!ready?'disabled':'required')+'><button type="button" id="entry-show-password" class="entry-link">'+t('Afficher','Show')+'</button></div><button type="button" class="entry-link" data-entry-go="recovery">'+t('Mot de passe oublié ?','Forgot password?')+'</button><button class="entry-submit" '+(!ready?'disabled':'')+'>'+t('Me connecter','Sign in')+'</button><p id="entry-login-status" role="status"></p></form><div class="entry-account-links"><button class="entry-link" data-entry-go="signup">'+t('Créer un compte','Create an account')+'</button><button class="entry-link" data-entry-go="invite">'+t('J’ai une invitation','I have an invitation')+'</button></div>'+(!cloud?'<button class="secondary" data-entry-go="worlds">'+t('Explorer la démonstration','Explore the demo')+'</button>':'<button class="secondary" data-entry-go="family">'+t('Retrouver mes enfants','View my children')+'</button>')+'</section>'+entryPattern()+'</section>';}
  let kids=1,kidsBound=false;
  const FAMILY_FIRST=2500,FAMILY_NEXT=1500,STUDENT=2000,TEACHER=5000,COACH=5000;
  const familyMonthly=n=>FAMILY_FIRST+FAMILY_NEXT*(n-1);
  function periodPrice(base){
    const months=billingPeriod==='annual'?12:billingPeriod==='quarterly'?3:1;
    const total=billingPeriod==='annual'?base*10:billingPeriod==='quarterly'?base*2.7:base;
    const fmt=n=>new Intl.NumberFormat(uiLanguage==='en'?'en-GB':'fr-FR',{maximumFractionDigits:0}).format(n);
    const saving=base*months-total;
    return fmt(total)+' FCFA <small>'+t('pour ','for ')+months+' '+t('mois','month'+(months===1?'':'s'))+' · '+t('à régler en une fois','paid in one payment')+'</small><small>'+(months>1?t('Soit environ ','About ')+fmt(total/months)+' FCFA / '+t('mois','month')+' · '+fmt(saving)+' FCFA '+t('économisés','saved'):t('Sans engagement · renouvelez quand vous le souhaitez.','No commitment · renew whenever you choose.'))+'</small>';
  }
  function periodSelector(){
    const options=[['monthly',t('Mensuel','Monthly'),t('Souplesse','Flexibility')],['quarterly',t('Trimestriel','Quarterly'),t('−10 %','−10%')],['annual',t('Annuel','Annual'),t('2 mois offerts','2 months included')]];
    const benefit=billingPeriod==='annual'?t('Douze mois de continuité, vacances comprises, au prix de dix mois.','Twelve months of continuity, including holidays, for the price of ten.'):billingPeriod==='quarterly'?t('Trois mois pour suivre une période de travail, avec 10 % d’économie.','Three months to follow a study period, with 10% savings.'):t('Un mois pour avancer à son rythme. Renouvelez seulement lorsque vous le souhaitez.','One month at your own pace. Renew only when you choose.');
    return '<div class="entry-periods" role="group" aria-label="'+t('Durée de l’abonnement','Subscription duration')+'">'+options.map(([key,label,badge])=>'<button class="secondary" data-billing-period="'+key+'" aria-pressed="'+(billingPeriod===key)+'">'+label+'<small>'+badge+'</small></button>').join('')+'</div><p class="entry-period-benefit" role="status">'+benefit+'</p>';
  }
